#include <stdlib.h>
#include <string.h>
#ifdef _OPENMP
#include <omp.h>
#endif
#if defined(__AVX512F__) || defined(__AVX2__)
#include <immintrin.h>
#endif

#define KC 256
#define NCBW 256

#if defined(__AVX512F__)

#define MR 12
#define NR 32

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int first, int mr, int nr)
{
#define DECL(i) __m512 c##i##_0 = _mm512_setzero_ps(), c##i##_1 = _mm512_setzero_ps();
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    DECL(6) DECL(7) DECL(8) DECL(9) DECL(10) DECL(11)
#undef DECL
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_loadu_ps(b);
        __m512 b1 = _mm512_loadu_ps(b + 16);
        __m512 t;
#define ROW(i) t = _mm512_set1_ps(a[i]); \
        c##i##_0 = _mm512_fmadd_ps(t, b0, c##i##_0); \
        c##i##_1 = _mm512_fmadd_ps(t, b1, c##i##_1);
        ROW(0) ROW(1) ROW(2) ROW(3) ROW(4) ROW(5)
        ROW(6) ROW(7) ROW(8) ROW(9) ROW(10) ROW(11)
#undef ROW
        a += MR;
        b += NR;
    }
    __mmask16 m0, m1;
    if (nr >= 32) { m0 = 0xFFFF; m1 = 0xFFFF; }
    else if (nr > 16) { m0 = 0xFFFF; m1 = (__mmask16)((1u << (nr - 16)) - 1); }
    else { m0 = (__mmask16)(nr == 16 ? 0xFFFF : ((1u << nr) - 1)); m1 = 0; }
#define ST(i) if (i < mr) { float *cr = c + (size_t)(i) * ldc; \
        if (first) { \
            _mm512_mask_storeu_ps(cr, m0, c##i##_0); \
            _mm512_mask_storeu_ps(cr + 16, m1, c##i##_1); \
        } else { \
            _mm512_mask_storeu_ps(cr, m0, _mm512_add_ps(c##i##_0, _mm512_maskz_loadu_ps(m0, cr))); \
            _mm512_mask_storeu_ps(cr + 16, m1, _mm512_add_ps(c##i##_1, _mm512_maskz_loadu_ps(m1, cr + 16))); \
        } }
    ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
    ST(6) ST(7) ST(8) ST(9) ST(10) ST(11)
#undef ST
}

#elif defined(__AVX2__) && defined(__FMA__)

#define MR 6
#define NR 16

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int first, int mr, int nr)
{
#define DECL(i) __m256 c##i##_0 = _mm256_setzero_ps(), c##i##_1 = _mm256_setzero_ps();
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
#undef DECL
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_loadu_ps(b);
        __m256 b1 = _mm256_loadu_ps(b + 8);
        __m256 t;
#define ROW(i) t = _mm256_broadcast_ss(a + i); \
        c##i##_0 = _mm256_fmadd_ps(t, b0, c##i##_0); \
        c##i##_1 = _mm256_fmadd_ps(t, b1, c##i##_1);
        ROW(0) ROW(1) ROW(2) ROW(3) ROW(4) ROW(5)
#undef ROW
        a += MR;
        b += NR;
    }
    if (mr == MR && nr == NR) {
#define ST(i) { float *cr = c + (size_t)(i) * ldc; \
        if (first) { _mm256_storeu_ps(cr, c##i##_0); _mm256_storeu_ps(cr + 8, c##i##_1); } \
        else { _mm256_storeu_ps(cr, _mm256_add_ps(c##i##_0, _mm256_loadu_ps(cr))); \
               _mm256_storeu_ps(cr + 8, _mm256_add_ps(c##i##_1, _mm256_loadu_ps(cr + 8))); } }
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
#undef ST
    } else {
        float tmp[MR][NR];
#define ST(i) _mm256_storeu_ps(tmp[i], c##i##_0); _mm256_storeu_ps(tmp[i] + 8, c##i##_1);
        ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
#undef ST
        for (int i = 0; i < mr; i++) {
            float *cr = c + (size_t)i * ldc;
            if (first) for (int j = 0; j < nr; j++) cr[j] = tmp[i][j];
            else       for (int j = 0; j < nr; j++) cr[j] += tmp[i][j];
        }
    }
}

#else

#define MR 4
#define NR 8

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int first, int mr, int nr)
{
    float acc[MR][NR];
    memset(acc, 0, sizeof(acc));
    for (int k = 0; k < kc; k++) {
        for (int i = 0; i < MR; i++)
            for (int j = 0; j < NR; j++)
                acc[i][j] += a[i] * b[j];
        a += MR;
        b += NR;
    }
    for (int i = 0; i < mr; i++) {
        float *cr = c + (size_t)i * ldc;
        if (first) for (int j = 0; j < nr; j++) cr[j] = acc[i][j];
        else       for (int j = 0; j < nr; j++) cr[j] += acc[i][j];
    }
}

#endif

#define PPB (NCBW / NR)

static float *bufA = NULL, *bufB = NULL;
static size_t capA = 0, capB = 0;

static float *ensure(float **buf, size_t *cap, size_t nfl)
{
    size_t bytes = (nfl * sizeof(float) + 63) & ~(size_t)63;
    if (bytes > *cap) {
        free(*buf);
        *buf = (float *)aligned_alloc(64, bytes);
        *cap = *buf ? bytes : 0;
    }
    return *buf;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int mp = (n + MR - 1) / MR;
    int np = (n + NR - 1) / NR;
    float *Ap = ensure(&bufA, &capA, (size_t)mp * MR * n);
    float *Bp = ensure(&bufB, &capB, (size_t)np * NR * n);

    int nth = 1;
#ifdef _OPENMP
    nth = omp_get_max_threads();
#endif
    int ntn = (np + PPB - 1) / PPB;
    int mpt = (mp * ntn) / (4 * nth);
    if (mpt < 1) mpt = 1;
    if (mpt > 8) mpt = 8;
    int mtn = (mp + mpt - 1) / mpt;
    int tasks = mtn * ntn;

#pragma omp parallel
    {
        /* Pack A: panels of MR rows, full k, layout [k][MR]. */
#pragma omp for schedule(static) nowait
        for (int ip = 0; ip < mp; ip++) {
            float *dst = Ap + (size_t)ip * MR * n;
            int r0 = ip * MR;
            int mr = n - r0 < MR ? n - r0 : MR;
            for (int r = 0; r < mr; r++) {
                const float *src = A + (size_t)(r0 + r) * n;
                for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = src[k];
            }
            for (int r = mr; r < MR; r++)
                for (int k = 0; k < n; k++) dst[(size_t)k * MR + r] = 0.0f;
        }
        /* Pack B: panels of NR columns, full k, layout [k][NR]. */
#pragma omp for schedule(static)
        for (int jp = 0; jp < np; jp++) {
            float *dst = Bp + (size_t)jp * NR * n;
            int c0 = jp * NR;
            int nr = n - c0 < NR ? n - c0 : NR;
            for (int k = 0; k < n; k++) {
                const float *src = B + (size_t)k * n + c0;
                float *d = dst + (size_t)k * NR;
                int j = 0;
                for (; j < nr; j++) d[j] = src[j];
                for (; j < NR; j++) d[j] = 0.0f;
            }
        }

#pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < tasks; t++) {
            int tj = t / mtn, ti = t % mtn;
            int p0 = ti * mpt, p1 = p0 + mpt < mp ? p0 + mpt : mp;
            int q0 = tj * PPB, q1 = q0 + PPB < np ? q0 + PPB : np;
            for (int pc = 0; pc < n; pc += KC) {
                int kc = n - pc < KC ? n - pc : KC;
                for (int p = p0; p < p1; p++) {
                    const float *ap = Ap + (size_t)p * MR * n + (size_t)pc * MR;
                    int mr = n - p * MR < MR ? n - p * MR : MR;
                    float *crow = C + (size_t)p * MR * n;
                    for (int q = q0; q < q1; q++) {
                        const float *bp = Bp + (size_t)q * NR * n + (size_t)pc * NR;
                        int nr = n - q * NR < NR ? n - q * NR : NR;
                        kernel(kc, ap, bp, crow + q * NR, n, pc == 0, mr, nr);
                    }
                }
            }
        }
    }
}
